select public.prepify_load_bank('English', 4, $j$[["The Brooklyn Bridge connects Brooklyn with:",["Manhattan","Queens","New Jersey","Staten Island"],"A",1,0,"34e0fb56ae45"],["The Brooklyn Bridge crosses the:",["Hudson River","East River","Thames","Mississippi"],"B",3,0,"74f27cdf5fe7"],["The engineer who first designed the Brooklyn Bridge was:",["Washington Roebling","John A. Roebling","Emily Roebling","Thomas Edison"],"B",1,0,"17147c3a102f"],["After John Roebling's death, the work was continued by his son:",["Washington Roebling","George Roebling","Henry Roebling","James Roebling"],"A",3,0,"b9791cbb8558"],["Emily Roebling is remembered because she:",["helped her injured husband complete the bridge","designed the Eiffel Tower","was the first mayor of New York","opposed the bridge"],"A",3,0,"8acb646f03c5"],["The Brooklyn Bridge is a:",["suspension bridge","wooden footbridge","floating bridge","drawbridge"],"A",3,0,"2faa0a6dc5d7"],["The Brooklyn Bridge was opened in:",["1783","1883","1933","1983"],"B",3,0,"298cd041143c"],["The main lesson of the story \"Nothing is Impossible\" is that:",["determination can overcome great obstacles","bridges are dangerous","engineers should give up","rivers cannot be crossed"],"A",1,0,"8223131e0778"],["Choose the synonym of \"spectacular\":",["Ordinary","Impressive","Tiny","Dull"],"B",1,0,"2a60fb31ac9e"],["Choose the antonym of \"possible\":",["Probable","Likely","Impossible","Easy"],"C",1,0,"b39eba87829b"],["Choose the correct spelling:",["Perseverance","Perseverence","Persevarance","Perserverance"],"A",3,0,"f9fd29960b0d"],["In \"The bridge was completed after many years\", the verb phrase is in the:",["active voice","passive voice","imperative mood","future tense"],"B",3,0,"091f9dd307f4"],["Choose the passive voice of \"Workers built the towers.\":",["The towers are built by workers.","The towers were built by workers.","The towers have been built by workers.","The towers were building by workers."],"B",3,0,"d29a67f4ef55"],["Although badly injured, Washington Roebling kept guiding the project from his room. Which quality does this show?",["Determination","Laziness","Fear","Carelessness"],"A",3,1,"7acf8261af41"],["Choose the synonym of \"obstacle\":",["Hurdle","Help","Reward","Path"],"A",1,0,"bd7c34d6319d"],["Fill in the blank: The engineers did not give ___ despite many problems.",["in","up","out","off"],"B",3,0,"c6aa58f9af61"],["In \"The determined engineer never quit\", the word \"determined\" is:",["a noun","a verb","an adjective","an adverb"],"C",3,0,"cd73a2a6b25a"],["Choose the correct sentence:",["Nothing are impossible.","Nothing is impossible.","Nothing be impossible.","Nothing were impossible."],"B",1,0,"c257d82d91ec"],["Choose the indirect speech of: The engineer said, \"We can build it.\"",["The engineer said that they could build it.","The engineer said that we can build it.","The engineer says that they could build it.","The engineer said that they can built it."],"A",5,0,"fc6e318a17d0"],["Which sentence is in the past continuous tense?",["They built a bridge.","They were building a bridge.","They have built a bridge.","They build a bridge."],"B",3,0,"c45dc0a295ba"],["Many people laughed at the idea of the bridge, but the Roeblings believed in it. This shows the Roeblings had:",["a strong vision","no plan","weak confidence","little interest"],"A",3,1,"459f90e3f433"],["Choose the correct article: It was ___ unique project in history.",["a","an","the","no article"],"A",5,0,"463548f2d9b0"],["Choose the antonym of \"courage\":",["Bravery","Fear","Boldness","Valour"],"B",1,0,"9be6a7ec878f"],["The suffix in \"achievement\" turns the verb \"achieve\" into a:",["noun","adjective","adverb","verb"],"A",3,0,"6c850df0013b"],["Choose the synonym of \"persistent\":",["Unwilling","Determined","Careless","Weak"],"B",3,0,"6add08eb102e"],["Fill in the blank: The bridge is famous ___ its beautiful design.",["at","for","with","by"],"B",3,0,"e00aadcae012"],["Choose the correctly punctuated sentence:",["The bridge, which opened in 1883, is still in use.","The bridge which opened in 1883, is still in use.","The bridge, which opened in 1883 is still in use.","The bridge which, opened in 1883 is still in use."],"A",5,0,"8c5c14cf9022"],["Which word is an adverb?",["Careful","Carefully","Care","Caring"],"B",1,0,"9f9ca9c3659b"],["If someone tells you a task is \"impossible\" and you keep trying until you succeed, you are proving that:",["hard work and patience can make the impossible possible","trying is useless","others are always right","success comes without effort"],"A",3,1,"e92dcd5150ca"],["Choose the plural of \"bridge\":",["bridgs","bridges","bridgies","bridgez"],"B",1,0,"3dc6730c691f"],["Choose the correct form: If they had given up, the bridge ___ never been built.",["will have","would have","has","had"],"B",5,0,"c39023ce684d"],["The suffix in \"enjoyment\" turns the verb \"enjoy\" into a:",["noun","adjective","adverb","verb"],"A",3,0,"6c850df0013b"],["Choose the indirect speech of: The workers said, \"We can finish it.\"",["The workers said that they could finish it.","The workers said that we can finish it.","The workers say that they could finish it.","The workers said that they can finished it."],"A",5,0,"fc6e318a17d0"],["Choose the synonym of \"determined\":",["Unwilling","Persistent","Careless","Weak"],"B",3,0,"6add08eb102e"],["Fill in the blank: Never give ___ your dreams, however hard the road.",["in","up","out","off"],"B",3,0,"c6aa58f9af61"],["Choose the synonym of \"impressive\":",["Ordinary","Spectacular","Tiny","Dull"],"B",1,0,"2a60fb31ac9e"],["In \"The towers were built of granite\", the verb phrase is in the:",["active voice","passive voice","imperative mood","future tense"],"B",3,0,"091f9dd307f4"],["Choose the antonym of \"impossible\":",["Unlikely","Hopeless","Possible","Difficult"],"C",1,0,"b39eba87829b"],["Choose the correct form: If the engineers had stopped, the bridge ___ never been finished.",["will have","would have","has","had"],"B",5,0,"c39023ce684d"],["People doubted the plan, but the builders kept faith in it. This shows the builders had:",["a strong vision","no plan","weak confidence","little interest"],"A",3,1,"459f90e3f433"]]$j$::jsonb, true);
select public.prepify_load_bank('English', 5, $j$[["Jeff Bezos is best known as the founder of:",["Microsoft","Amazon","Facebook","Apple"],"B",1,0,"22f3ca58ddda"],["Amazon began as an online store selling:",["books","cars","medicines","furniture"],"A",1,0,"05f5bf1be9b4"],["Amazon was founded in:",["1974","1984","1994","2004"],"C",3,0,"453e31f303b4"],["A lesson often linked with Jeff Bezos is to focus first on:",["the customer","the competitor","shortcuts","luck"],"A",3,0,"0987bec39f11"],["Thinking \"long-term\" in business means:",["planning for results years ahead rather than quick gains","wanting results today only","avoiding all planning","copying others"],"A",3,0,"59f7cc294624"],["Choose the synonym of \"success\":",["Failure","Achievement","Loss","Defeat"],"B",1,0,"bb0fc0cbc32f"],["Choose the antonym of \"failure\":",["Success","Mistake","Loss","Fall"],"A",1,0,"4b3c36dfa542"],["Choose the correct spelling:",["Succesful","Successful","Sucessful","Successfull"],"B",1,0,"a17b03798a16"],["Bilal's first online shop fails, but he studies his mistakes and tries again with a better plan. Which lesson is he following?",["Learn from failure and keep trying","Never start anything new","Blame others","Give up after one attempt"],"A",3,1,"b7160b365808"],["In \"Bezos worked patiently for years\", the word \"patiently\" is:",["an adjective","an adverb","a noun","a pronoun"],"B",1,0,"2a1b99208f71"],["Choose the passive voice of \"He founded a company.\":",["A company is founded by him.","A company was founded by him.","A company had founded him.","A company was founding by him."],"B",3,0,"ae8c3da2f4b4"],["Fill in the blank: Success depends ___ hard work.",["at","on","in","with"],"B",3,0,"9865a95e108a"],["Choose the correct sentence:",["He have many ideas.","He has many ideas.","He having many ideas.","He hasing many ideas."],"B",1,0,"7f2179df7151"],["Which sentence is in the simple future tense?",["He will start a company.","He starts a company.","He started a company.","He is starting a company."],"A",1,0,"e5173e5edf95"],["Choose the synonym of \"innovation\":",["New idea","Old habit","Copy","Delay"],"A",3,0,"a1c9574a664c"],["Choose the indirect speech of: He said, \"Customers come first.\"",["He said that customers came first.","He said that customers come firstly.","He says that customers came first.","He said customers coming first."],"A",5,0,"a3ad272f077e"],["A shop owner listens to complaints and quickly improves his service. He is showing:",["customer focus","carelessness","pride","laziness"],"A",3,1,"2bc2de940c0d"],["Choose the word that is a noun:",["Ambitious","Ambition","Ambitiously","Ambit"],"B",1,0,"52f7aa99e669"],["Choose the antonym of \"risky\":",["Dangerous","Safe","Bold","Uncertain"],"B",1,0,"c3480298ee05"],["Choose the correct article: He had ___ idea to sell books online.",["a","an","the","no article"],"B",1,0,"92492177ca91"],["Fill in the blank: He was ready ___ take risks.",["for","to","at","on"],"B",1,0,"895cc719a13e"],["Choose the correctly punctuated sentence:",["\"Work hard,\" he said, \"and never give up.\"","\"Work hard\" he said \"and never give up.\"","\"Work hard, he said, and never give up.\"","Work hard, he said, \"and never give up\"."],"A",5,0,"ffdcc285e820"],["Which sentence is in the present continuous tense?",["Amazon grows fast.","Amazon is growing fast.","Amazon grew fast.","Amazon has grown fast."],"B",1,0,"9b6c69a6da67"],["Choose the synonym of \"persistent\":",["Stubbornly determined","Easily discouraged","Lazy","Forgetful"],"A",3,0,"a244676f91a8"],["Two students start small businesses. One gives up after a bad month; the other adjusts her prices and continues. Who is showing the entrepreneurial mindset?",["The one who adjusts and continues","The one who gives up","Both equally","Neither"],"A",3,1,"7a8877262d46"],["Choose the correct form of the verb: If you work hard, you ___ succeed.",["will","would","had","were"],"A",5,0,"1afffe380957"],["The prefix \"re-\" in \"rethink\" means:",["again","not","before","against"],"A",1,0,"528d73e3c8d6"],["Choose the adjective in: \"He made a bold decision.\"",["He","made","bold","decision"],"C",1,0,"fb4565b435da"],["Choose the plural of \"company\":",["companys","companies","companyes","companis"],"B",1,0,"a963bca62657"],["\"Regret\" means:",["a feeling of sadness about something done or not done","a feeling of great joy","a kind of reward","a type of business"],"A",3,0,"3fae6af431b3"],["Choose the indirect speech of: She said, \"Hard work pays.\"",["She said that hard work paid.","She said that hard work pays hardly.","She says that hard work paid.","She said that hard work will pay."],"A",5,0,"a3ad272f077e"],["In \"She listened carefully to her customers\", the word \"carefully\" is:",["an adjective","an adverb","a noun","a pronoun"],"B",1,0,"2a1b99208f71"],["Choose the antonym of \"success\":",["Failure","Victory","Win","Gain"],"A",1,0,"4b3c36dfa542"],["Choose the plural of \"opportunity\":",["opportunitys","opportunities","opportunityes","opportunitis"],"B",1,0,"a963bca62657"],["Choose the antonym of \"safe\":",["Secure","Protected","Risky","Calm"],"C",1,0,"c3480298ee05"],["Fill in the blank: She was eager ___ learn new skills.",["for","to","at","on"],"B",1,0,"895cc719a13e"],["Fill in the blank: Good results depend ___ regular practice.",["at","on","in","with"],"B",3,0,"9865a95e108a"],["Usman's first food stall loses money, so he studies what went wrong and opens a better one. Which lesson is he following?",["Learn from failure and keep trying","Never start again","Blame others","Copy competitors exactly"],"A",3,1,"b7160b365808"],["A shopkeeper changes his stock after listening to what his buyers want. He is focusing first on:",["the customer","the competitor","shortcuts","luck"],"A",3,1,"0987bec39f11"]]$j$::jsonb, true);
select public.prepify_load_bank('English', 6, $j$[["\"Addiction\" means:",["a strong, harmful dependence on something","a healthy hobby","a kind of medicine","a sports activity"],"A",1,0,"6e80bda8aa5f"],["\"Peer pressure\" means:",["influence from people of your own age group","pressure of air","pressure from teachers only","a medical test"],"A",1,0,"e4b252610207"],["A friend offers Usman a cigarette and says everyone in the group smokes. Refusing firmly and walking away shows:",["resisting peer pressure","peer pressure","addiction","rudeness"],"A",3,1,"15fa2560834f"],["\"Rehabilitation\" means:",["helping a person recover and return to normal life","punishing a person","selling drugs","a kind of exercise"],"A",3,0,"f5b1cf4ac473"],["Choose the synonym of \"harmful\":",["Damaging","Useful","Safe","Healthy"],"A",1,0,"d3b14a1fa374"],["Choose the antonym of \"healthy\":",["Fit","Strong","Unhealthy","Active"],"C",1,0,"e1341ea54263"],["Choose the correct spelling:",["Adiction","Addiction","Addicshun","Adicttion"],"B",1,0,"a3a6995907ad"],["In \"Drugs destroy lives\", the verb is:",["Drugs","destroy","lives","none"],"B",1,0,"a0c6a2971cee"],["Choose the passive voice of \"Drugs ruin many young lives.\":",["Many young lives are ruined by drugs.","Many young lives were ruined by drugs.","Many young lives ruined by drugs.","Many young lives are ruining by drugs."],"A",3,0,"5d1d49d64f9c"],["Fill in the blank: We must say no ___ drugs.",["at","to","on","with"],"B",1,0,"8a08e02b614a"],["Choose the correct sentence:",["Drugs is dangerous.","Drugs are dangerous.","Drugs be dangerous.","Drugs was dangerous."],"B",1,0,"96c2261fa071"],["Which word is an adjective?",["Danger","Dangerous","Dangerously","Endanger"],"B",1,0,"129f6894010c"],["A teenager starts missing school, loses interest in family and becomes secretive after mixing with a new group. What should his family do first?",["Talk to him calmly and seek help","Ignore the change","Punish him without asking","Give him more money"],"A",3,1,"d0346253c50e"],["Choose the synonym of \"abstain\":",["Refrain","Indulge","Continue","Consume"],"A",5,0,"e350b0521c48"],["Choose the indirect speech of: The doctor said, \"Drugs damage the brain.\"",["The doctor said that drugs damaged the brain.","The doctor said that drugs damage the brain.","The doctor says that drugs damaged the brain.","The doctor said drugs damaging the brain."],"B",5,0,"133b7342cc3e"],["Which sentence is in the present perfect tense?",["He quits smoking.","He has quit smoking.","He quit smoking.","He will quit smoking."],"B",3,0,"4268041322b0"],["Choose the correct article: Drug abuse is ___ serious problem.",["a","an","the","no article"],"A",1,0,"11bbcddc8960"],["Choose the antonym of \"dependent\":",["Reliant","Independent","Addicted","Attached"],"B",1,0,"86111afac4e4"],["The prefix \"anti-\" in \"anti-drug campaign\" means:",["against","for","before","after"],"A",1,0,"3113b81358aa"],["Fill in the blank: He was addicted ___ drugs for years.",["on","to","with","at"],"B",3,0,"67a6b7c5392e"],["Choose the correctly punctuated sentence:",["Drugs harm your body, mind, and future.","Drugs harm your body mind and future.","Drugs harm, your body, mind and future","drugs harm your body, mind, and future."],"A",3,0,"89a6108639b7"],["Choose the synonym of \"consequence\":",["Result","Cause","Reason","Beginning"],"A",3,0,"6599e931e851"],["Choose the word that is a noun:",["Recover","Recovery","Recovering","Recovered"],"B",1,0,"b7e14f7f9567"],["A student joins a sports club and makes new friends there after leaving a group that used drugs. This shows:",["choosing a healthy lifestyle","peer pressure","addiction","withdrawal"],"A",3,1,"bc9ed2415576"],["Choose the correct form: If you ___ drugs, you will ruin your health.",["take","took","taken","taking"],"A",5,0,"420a40859792"],["Choose the synonym of \"awareness\":",["Knowledge","Ignorance","Sleep","Doubt"],"A",1,0,"834c99e0e148"],["\"Withdrawal symptoms\" are:",["the unpleasant effects felt when a person stops taking an addictive drug","the benefits of exercise","signs of good health","symptoms of a cold"],"A",3,0,"41e27f52dace"],["Which sentence is an exclamation?",["Drugs are harmful.","Stay away from drugs.","What a terrible habit drug abuse is!","Are drugs harmful?"],"C",1,0,"5ed1f439a7f3"],["Choose the plural of \"life\":",["lifes","lives","lifs","livies"],"B",1,0,"fbdb9159765c"],["Choose the plural of \"knife\":",["knifes","knives","knifs","knivies"],"B",1,0,"fbdb9159765c"],["Which sentence is an exclamation?",["Smoking is harmful.","Stop smoking now.","How harmful smoking is!","Is smoking harmful?"],"C",1,0,"5ed1f439a7f3"],["Choose the correct form: If you ___ bad company, you will regret it.",["keep","kept","kept up","keeping"],"A",5,0,"420a40859792"],["Which sentence is in the present perfect tense?",["She leaves the gang.","She has left the gang.","She left the gang.","She will leave the gang."],"B",3,0,"4268041322b0"],["Choose the passive voice of \"Drugs destroy families.\":",["Families are destroyed by drugs.","Families were destroyed by drugs.","Families destroyed by drugs.","Families have destroyed drugs."],"A",3,0,"5d1d49d64f9c"],["Choose the correct spelling:",["Rehabilitasion","Rehabilitation","Rehabbilitation","Rehabilitaton"],"B",1,0,"a3a6995907ad"],["The prefix \"anti-\" in \"antisocial\" means:",["against","for","before","after"],"A",1,0,"3113b81358aa"],["Which word is an adjective?",["Harm","Harmful","Harmfully","Harming"],"B",1,0,"129f6894010c"],["Fill in the blank: Young people should stay away ___ drugs.",["at","from","on","with"],"B",1,0,"8a08e02b614a"],["Ali stops meeting friends who use drugs and joins a cricket team instead. This shows:",["choosing a healthy lifestyle","peer pressure","addiction","withdrawal"],"A",1,1,"bc9ed2415576"]]$j$::jsonb, true);
select public.prepify_load_bank('English', 7, $j$[["\"Mowing\" was written by:",["William Wordsworth","Robert Frost","Alfred Tennyson","John Keats"],"B",1,0,"8b71c0f0d39e"],["Robert Frost was a poet from:",["England","America","Scotland","India"],"B",1,0,"a4f641604b21"],["In \"Mowing\", the speaker is cutting grass with a:",["lawnmower","scythe","knife","sickle machine"],"B",1,0,"aa1d4cf7d081"],["In the poem, the only sound beside the wood is:",["the birds singing","the scythe whispering to the ground","the wind blowing","a stream flowing"],"B",3,0,"ce4daa85cabd"],["\"My long scythe whispering to the ground\" is an example of:",["simile","personification","rhyme","onomatopoeia only"],"B",3,0,"ea5d25b52971"],["\"The fact is the sweetest dream that labor knows\" suggests that:",["real, honest work is more satisfying than daydreams","dreams are better than work","labour is useless","facts are boring"],"A",5,0,"14f3acca93b2"],["The poem celebrates the:",["dignity of hard work","life in cities","joy of wealth","love of travel"],"A",1,0,"b203a53eeef9"],["A \"scythe\" is:",["a long-handled tool with a curved blade for cutting grass","a musical instrument","a type of snake","a farm animal"],"A",1,0,"012ea998a642"],["\"Mowing\" has fourteen lines, which means it is a:",["ballad","sonnet","limerick","haiku"],"B",3,0,"1c5bfceb3c2e"],["The speaker says the work was \"no dream of the gift of idle hours\". This means the work was:",["real and earnest, not lazy fantasy","a dream he had while sleeping","a gift from fairies","done in idle hours"],"A",5,0,"a9bb1d91a61a"],["In the poem, \"fay or elf\" refers to:",["farmers","fairies","snakes","flowers"],"B",3,0,"199c2b9e888b"],["While mowing, the speaker scares a:",["bright green snake","little rabbit","flock of birds","stray dog"],"A",3,0,"4b6985dfe219"],["\"Swale\" means:",["a low, marshy piece of land","a high mountain","a sandy beach","a busy road"],"A",5,0,"ddbb6e38012e"],["A farmer feels proud after harvesting his crop with his own hands, even though it was tiring. This feeling matches the poem's idea that:",["honest labour brings true satisfaction","work should be avoided","only rich people are happy","machines are better than people"],"A",3,1,"368286c98eeb"],["Choose the synonym of \"earnest\":",["Serious and sincere","Careless","Funny","Lazy"],"A",3,0,"9a10fc7b7bf7"],["Choose the antonym of \"feeble\":",["Weak","Frail","Strong","Faint"],"C",1,0,"9643b40eb88b"],["Choose the correct spelling:",["Whisper","Wisper","Whispar","Whissper"],"A",1,0,"747a63175977"],["In \"The scythe whispered softly\", the word \"softly\" is:",["an adjective","an adverb","a noun","a verb"],"B",1,0,"6de74ba83909"],["Choose the passive voice of \"He mowed the field.\":",["The field is mowed by him.","The field was mowed by him.","The field has mowed him.","The field was mowing by him."],"B",3,0,"c53080cd1d59"],["\"Pale orchises\" in the poem are a kind of:",["flower","insect","stone","cloud"],"A",3,0,"2c00a9da749e"],["Choose the correct sentence:",["The poet describe his work.","The poet describes his work.","The poet describing his work.","The poet have described his work."],"B",1,0,"18be4f903487"],["The mood of \"Mowing\" is mainly:",["calm and thoughtful","angry and loud","scared","playful and silly"],"A",3,0,"4f87459e7bf1"],["Choose the synonym of \"labour\":",["Work","Rest","Sleep","Play"],"A",1,0,"5eb549a5df47"],["In \"the heat of the sun\", \"heat\" is a:",["verb","noun","adjective","adverb"],"B",1,0,"c3197144816b"],["Fill in the blank: The speaker takes pride ___ his work.",["on","in","at","with"],"B",3,0,"c09ac24dcee4"],["The word \"idle\" in \"idle hours\" means:",["busy","not working or doing nothing useful","angry","bright"],"B",3,0,"8179e808cc1e"],["Choose the indirect speech of: The farmer said, \"I love my work.\"",["The farmer said that he loved his work.","The farmer said that I love my work.","The farmer says that he loved his work.","The farmer said that he loves my work."],"A",5,0,"13f887f228b5"],["The speaker hears the scythe \"whisper\" but cannot tell exactly what it says. This shows the poet leaves the meaning:",["open for the reader to think about","completely explained","as a joke","as a list of facts"],"A",5,0,"eb1402abce4e"],["The word \"idle\" in \"an idle afternoon\" means:",["busy","not working or doing nothing useful","angry","noisy"],"B",3,0,"8179e808cc1e"],["Choose the indirect speech of: The gardener said, \"I enjoy my work.\"",["The gardener said that he enjoyed his work.","The gardener said that I enjoy my work.","The gardener says that he enjoyed his work.","The gardener said that he enjoys my work."],"A",5,0,"13f887f228b5"],["A poem of fourteen lines, such as Robert Frost's \"Mowing\", is called a:",["ballad","sonnet","limerick","haiku"],"B",1,0,"1c5bfceb3c2e"],["Choose the synonym of \"sincere\":",["Earnest","Careless","Funny","Lazy"],"A",3,0,"9a10fc7b7bf7"],["Choose the antonym of \"strong\":",["Mighty","Powerful","Feeble","Sturdy"],"C",1,0,"9643b40eb88b"],["Choose the synonym of \"work\":",["Labour","Rest","Sleep","Play"],"A",1,0,"5eb549a5df47"],["The central message of \"Mowing\" is:",["the dignity of honest hard work","the excitement of city life","the value of money","the joy of travelling"],"A",3,0,"b203a53eeef9"],["In \"Mowing\", the scythe is said to \"whisper\". Giving a tool a human action like this is:",["personification","simile","alliteration","exaggeration"],"A",5,0,"ce4daa85cabd"]]$j$::jsonb, true);
select public.prepify_load_bank('English', 8, $j$[["\"The Eagle\" was written by:",["Robert Frost","Alfred Tennyson","William Shakespeare","John Milton"],"B",1,0,"66b708288e7c"],["Alfred Tennyson was a poet from:",["England","America","Pakistan","France"],"A",1,0,"e5786c3c76c8"],["\"He clasps the crag with crooked hands\" — the repeated \"c/k\" sound is an example of:",["simile","alliteration","metaphor","irony"],"B",3,0,"004c65303259"],["Calling the eagle's claws \"crooked hands\" is an example of:",["personification","simile","alliteration only","hyperbole"],"A",3,0,"0450496afddc"],["\"And like a thunderbolt he falls\" is an example of:",["metaphor","simile","personification","onomatopoeia"],"B",1,0,"64b4e467b384"],["In the poem, a \"crag\" is:",["a steep, rugged rock","a river bank","a nest","a cloud"],"A",3,0,"e091dc39e315"],["\"Ringed with the azure world\" means the eagle is:",["surrounded by the blue sky","wearing a ring","trapped in a cage","covered in snow"],"A",3,0,"6781e9baaea4"],["\"Azure\" means:",["bright blue","dark green","deep red","pure white"],"A",1,0,"ea926de3c568"],["\"The wrinkled sea beneath him crawls\" suggests that from the eagle's height the sea looks:",["small, slow and rippled","very close and loud","dry and empty","frozen"],"A",5,0,"e97d37fca5a9"],["The eagle \"falls\" at the end of the poem most likely to:",["swoop down on its prey","die of old age","escape a storm","build its nest"],"A",5,0,"65f1d85e5339"],["\"The Eagle\" consists of:",["two stanzas of three lines each","one stanza of fourteen lines","three stanzas of four lines","four stanzas of two lines"],"A",3,0,"3c14ff6a905f"],["The rhyme scheme of \"The Eagle\" is:",["AAA BBB","ABAB CDCD","AABB CCDD","ABCABC"],"A",5,0,"64fa0ccdda5d"],["The eagle is described as standing \"close to the sun in lonely lands\". This shows that it lives:",["high up and alone","in crowded forests","near the sea shore","in a zoo"],"A",3,0,"c73a999d8ea4"],["The overall picture of the eagle in the poem is one of:",["power and majesty","weakness and fear","laziness","foolishness"],"A",1,0,"3856e7da2af3"],["A student describes a cheetah as \"running like the wind\". Which device from the poem is the student also using?",["Simile","Alliteration","Personification","Rhyme scheme"],"A",3,1,"eedc09739965"],["Choose the synonym of \"lonely\":",["Solitary","Crowded","Busy","Cheerful"],"A",1,0,"438c2d9da94e"],["Choose the antonym of \"beneath\":",["Below","Under","Above","Down"],"C",1,0,"9a3467700283"],["Choose the correct spelling:",["Thunderbolt","Thunderbolte","Thundarbolt","Thunderbollt"],"A",1,0,"464ef8a16614"],["In \"The eagle falls swiftly\", \"swiftly\" is:",["an adjective","an adverb","a noun","a verb"],"B",1,0,"e18498006527"],["Choose the passive voice of \"The eagle caught a fish.\":",["A fish is caught by the eagle.","A fish was caught by the eagle.","A fish has caught the eagle.","A fish was catching by the eagle."],"B",3,0,"6e2c06a64152"],["Choose the correct sentence:",["The eagle watch from the mountain.","The eagle watches from the mountain.","The eagle watching from the mountain.","The eagle have watched from the mountain."],"B",1,0,"a9a88bdbc7e8"],["In \"He watches from his mountain walls\", \"mountain walls\" refers to:",["the steep sides of the mountains","walls of a castle","walls of a house","a prison"],"A",3,0,"ef0e56816762"],["Fill in the blank: The eagle is famous ___ its sharp eyesight.",["for","of","at","by"],"A",1,0,"4f43b8dd54d2"],["Choose the plural of \"eagle\":",["eagles","eagless","eagels","eaglies"],"A",1,0,"d8364a12a477"],["Which word best describes the tone of the poem?",["Vivid and powerful","Sad and weeping","Humorous","Confused"],"A",3,0,"a686d89f7fcd"],["Choose the indirect speech of: The teacher said, \"Eagles fly very high.\"",["The teacher said that eagles fly very high.","The teacher said that eagles flew very high always.","The teacher says that eagles flew very high.","The teacher said eagles flying very high."],"A",5,0,"75202d606105"],["A writer says, \"The angry clouds shouted at the town.\" Which device is this, the same one Tennyson uses for \"the wrinkled sea crawls\"?",["Personification","Simile","Alliteration","Rhyme"],"A",3,1,"a7faa7117f04"],["Choose the indirect speech of: The teacher said, \"The sun rises in the east.\"",["The teacher said that the sun rises in the east.","The teacher said that the sun rose in the east always.","The teacher says that the sun rose in the east.","The teacher said that the sun will rise in the east."],"A",5,0,"75202d606105"],["A poet writes, \"Her smile was as bright as the sun.\" Which device is this?",["Simile","Alliteration","Personification","Rhyme"],"A",3,1,"eedc09739965"],["\"The wind howled angrily at the window\" gives the wind a human feeling. This is:",["personification","simile","alliteration","a question"],"A",3,1,"a7faa7117f04"],["Choose the passive voice of \"The eagle watched the sea.\":",["The sea is watched by the eagle.","The sea was watched by the eagle.","The sea has watched the eagle.","The sea was watch by the eagle."],"B",3,0,"6e2c06a64152"],["In \"The Eagle\", the \"azure world\" around the bird is the:",["blue sky","green forest","dark night","snowy mountain"],"A",3,0,"6781e9baaea4"],["Choose the synonym of \"solitary\":",["Lonely","Crowded","Busy","Cheerful"],"A",1,0,"438c2d9da94e"],["Fill in the blank: Pakistan is famous ___ its mountains.",["for","of","at","by"],"A",1,0,"4f43b8dd54d2"],["\"He clasps the crag with crooked hands\" describes the eagle's claws as hands. This is an example of:",["personification","simile","alliteration only","a question"],"A",3,0,"0450496afddc"]]$j$::jsonb, true);
select public.prepify_load_bank('English', 9, $j$[["\"Tourism\" means:",["travelling to places for pleasure, learning or leisure","staying at home all year","working in a factory","studying at school"],"A",1,0,"cad806b6eedb"],["K2, the second-highest mountain in the world, is located in:",["Pakistan","Nepal","China only","India"],"A",1,0,"32e9ecb9c27c"],["The ancient city of Mohenjo-daro belongs to the:",["Indus Valley Civilization","Roman Empire","Mughal Empire","Greek civilization"],"A",3,0,"9d8835875df3"],["The Badshahi Mosque and the Lahore Fort are both in:",["Karachi","Lahore","Peshawar","Quetta"],"B",1,0,"749ad8d9d710"],["A \"souvenir\" is:",["something bought to remember a place","a type of hotel","a travel ticket","a tour guide"],"A",3,0,"173bdade579c"],["An \"itinerary\" is:",["a planned route or schedule of a journey","a travel bag","a hotel bill","a foreign coin"],"A",3,0,"24d26a42473f"],["Choose the synonym of \"journey\":",["Trip","Rest","Stay","Halt"],"A",1,0,"eac1df867c64"],["Choose the antonym of \"arrival\":",["Coming","Entry","Departure","Landing"],"C",1,0,"5574a4c63be0"],["Choose the correct spelling:",["Accommodation","Accomodation","Acommodation","Accommadation"],"A",5,0,"cd0737d3b69c"],["Hina plans a trip to Hunza, books a hotel, and lists places to visit each day. The list she makes is her:",["itinerary","souvenir","passport","receipt"],"A",3,1,"ea91c4d37234"],["\"Hospitality\" means:",["a friendly and generous welcome to guests","a hospital visit","a travel document","a hotel room"],"A",3,0,"557e457a86f0"],["Tourism helps a country's economy mainly by:",["bringing income and creating jobs","reducing all trade","closing businesses","increasing pollution only"],"A",3,0,"d98e5250c99e"],["Choose the passive voice of \"Tourists visit the northern areas every summer.\":",["The northern areas are visited by tourists every summer.","The northern areas were visited by tourists every summer.","The northern areas visited by tourists every summer.","The northern areas are visiting by tourists every summer."],"A",3,0,"6e503c7062ff"],["Fill in the blank: We are going ___ a trip to Swat.",["in","on","at","by"],"B",3,0,"7c087090b931"],["Choose the correct sentence:",["We visited Naran last year.","We visit Naran last year.","We have visited Naran last year.","We visiting Naran last year."],"A",5,0,"79e438d947b3"],["Which sentence is in the future tense?",["They travelled to Skardu.","They will travel to Skardu.","They travel to Skardu.","They are travelling to Skardu now."],"B",1,0,"39b7e339f01e"],["In \"The valley is beautiful\", the word \"beautiful\" is:",["a noun","an adjective","an adverb","a verb"],"B",1,0,"f3c454d65952"],["A group of tourists leaves plastic bottles along a mountain trail. Which responsible-tourism rule are they breaking?",["Keep the environment clean","Respect local culture","Book hotels early","Carry a map"],"A",3,1,"b6b9ffee420c"],["Choose the synonym of \"destination\":",["Starting point","Place one is travelling to","Hotel","Luggage"],"B",3,0,"bde570dee600"],["Choose the indirect speech of: The guide said, \"The lake is very deep.\"",["The guide said that the lake was very deep.","The guide said that the lake is very deeply.","The guide says that the lake was very deep.","The guide said the lake being very deep."],"A",5,0,"9a085cd4c299"],["Choose the correct article: Murree is ___ popular hill station.",["a","an","the","no article"],"A",1,0,"df69c5d16d81"],["Choose the correctly punctuated sentence:",["We visited Hunza, Skardu, and Gilgit.","We visited Hunza Skardu and Gilgit.","We visited, Hunza, Skardu and Gilgit.","we visited Hunza, Skardu, and Gilgit."],"A",1,0,"1ea05248bfac"],["Choose the plural of \"journey\":",["journies","journeys","journeyes","journys"],"B",5,0,"4a0c595f8647"],["Choose the synonym of \"scenic\":",["Picturesque","Ugly","Dull","Crowded"],"A",3,0,"e61d052e6fef"],["Fill in the blank: Pakistan is rich ___ natural beauty.",["with","in","at","of"],"B",3,0,"b0fe6f5e59cb"],